var e={klipperscreenStudio:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Edit konfigurasi layar sentuh KlipperScreen printer Anda dengan aman, lalu restart KlipperScreen untuk menerapkannya. Setiap penyimpanan dicadangkan terlebih dahulu.`}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Bantuan`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Tentang KlipperScreen Studio`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Tutup`}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:`Cara membaca`}},steps:[{t:0,b:{t:2,i:[{t:3}],s:`Edit teks konfigurasi di bawah (atau biarkan apa adanya).`}},{t:0,b:{t:2,i:[{t:3}],s:`Simpan - file saat ini dicadangkan terlebih dahulu, dan penyimpanan ditolak saat printer sedang sibuk.`}},{t:0,b:{t:2,i:[{t:3}],s:`Restart KlipperScreen untuk menerapkan perubahan pada layar fisik.`}},{t:0,b:{t:2,i:[{t:3}],s:`Baris menggunakan akhiran UNIX (LF), diberlakukan otomatis saat menyimpan.`}}],topics:{glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glosarium`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Definisi singkat istilah KlipperScreen yang digunakan di sini.`}}},config:{title:{t:0,b:{t:2,i:[{t:3}],s:`Apa itu tab Config?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`File KlipperScreen.conf mentah. Edit pengaturan apa pun secara manual; penyimpanan mencadangkan file terlebih dahulu, ditolak saat printer sibuk, dan memperingatkan jika file berubah di layar sejak Anda memuatnya. Kebanyakan orang menggunakan tab Settings / Menus / Themes sebagai gantinya.`}}},settings:{title:{t:0,b:{t:2,i:[{t:3}],s:`Apa itu tab Settings?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Opsi [main] yang paling sering dipakai dalam bentuk formulir - tema, bahasa, sleep layar, ukuran font, dan saklar. Terisi otomatis dari konfigurasi aktif; hanya opsi yang Anda ubah yang ditulis. Restart untuk menerapkan.`}}},menus:{title:{t:0,b:{t:2,i:[{t:3}],s:`Apa itu tab Menus?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Rancang grid tombol layar sentuh. Setiap pohon (__main adalah grid beranda, __print layar cetak) mencantumkan tombolnya; tambah, ganti nama, urutkan ulang, dan susun bertingkat, lalu atur masing-masing untuk membuka sub-menu, membuka layar bawaan, atau menjalankan G-code.`}}},themes:{title:{t:0,b:{t:2,i:[{t:3}],s:`Apa itu tab Themes?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Buat tema KlipperScreen: pilih warna per token palet dan radius sudut, amati pratinjau langsung, lalu buat dan terapkan ke layar. Pratinjau bersifat perkiraan - layar sebenarnya dirender dengan GTK.`}}},kiosk:{title:{t:0,b:{t:2,i:[{t:3}],s:`Apa itu tab Kiosk?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Tampilkan FilaMind Flow sendiri di layar sentuh sebagai peramban layar penuh - kendali total atas apa yang ditampilkan layar. Ini pertukaran yang dapat dibalik dengan KlipperScreen (sementara secara default; reboot memulihkan KlipperScreen). Membutuhkan pemasang sekali jalan di host printer.`}}}},glossary:{klipperScreen:{term:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Antarmuka layar sentuh yang berjalan di layar kecil terpasang pada printer - terpisah dari panel web ini.`}}},theme:{term:{t:0,b:{t:2,i:[{t:3}],s:`Tema`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Tampilan KlipperScreen - warna, ikon, dan radius sudut. Tersimpan di folder styles/<name> pada host; hanya kosmetik (tidak bisa mengubah tata letak).`}}},menu:{term:{t:0,b:{t:2,i:[{t:3}],s:`Menu (__main / __print)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Grid tombol yang ditampilkan KlipperScreen. __main adalah layar beranda, __print layar yang ditampilkan saat mencetak, __splashscreen layar awal.`}}},panel:{term:{t:0,b:{t:2,i:[{t:3}],s:`Panel`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Layar bawaan KlipperScreen yang dapat dibuka oleh sebuah tombol (gerak, suhu, ekstrusi, bed mesh, …). Isi internalnya ditetapkan oleh KlipperScreen.`}}},autoBlock:{term:{t:0,b:{t:2,i:[{t:3}],s:`Blok yang dibuat otomatis (#~#)`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Bagian yang ditulis KlipperScreen untuk dirinya sendiri di bawah conf, setelah penanda #~#. FilaMind tidak pernah mengeditnya - hanya pengaturan Anda di atasnya.`}}},kiosk:{term:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Menjalankan peramban layar penuh di layar sentuh alih-alih KlipperScreen, sehingga layar menampilkan FilaMind Flow. Sepenuhnya dapat dibalik.`}}}}},status:{checking:{t:0,b:{t:2,i:[{t:3}],s:`Memeriksa KlipperScreen…`}},absent:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen tidak terdeteksi pada printer ini (tidak ada KlipperScreen.conf, dan tidak dilaporkan oleh Moonraker). Pasang KlipperScreen untuk menggunakan alat ini.`}},present:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen terdeteksi`}},theme:{t:0,b:{t:2,i:[{t:3}],s:`Tema`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Bahasa`}},notRestartable:{t:0,b:{t:2,i:[{t:3}],s:`Moonraker tidak dapat me-restart KlipperScreen secara otomatis - restart secara manual setelah menyimpan.`}}},editor:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Membaca KlipperScreen.conf…`}},reload:{t:0,b:{t:2,i:[{t:3}],s:`Muat ulang`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Simpan konfigurasi`}},saving:{t:0,b:{t:2,i:[{t:3}],s:`Menyimpan…`}},saved:{t:0,b:{t:2,i:[{t:3}],s:`Tersimpan (dicadangkan)`}},unsaved:{t:0,b:{t:2,i:[{t:3}],s:`Perubahan belum disimpan`}}},save:{busy:{t:0,b:{t:2,i:[{t:3}],s:`Ditolak saat printer sibuk - coba lagi saat menganggur.`}},stale:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen.conf berubah di disk sejak dimuat (kemungkinan diedit di layar). Muat ulang sebelum menyimpan agar Anda tidak menimpa perubahan itu.`}}},view:{config:{t:0,b:{t:2,i:[{t:3}],s:`Config`}},settings:{t:0,b:{t:2,i:[{t:3}],s:`Settings`}},menus:{t:0,b:{t:2,i:[{t:3}],s:`Menus`}},themes:{t:0,b:{t:2,i:[{t:3}],s:`Themes`}},kiosk:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk`}},fmscreen:{t:0,b:{t:2,i:[{t:3}],s:`Layar FilaMind`}}},settings:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Memuat pengaturan…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Opsi tampilan KlipperScreen yang paling sering dipakai dalam bentuk formulir. Hanya opsi yang Anda ubah yang ditulis - sisanya mempertahankan nilai saat ini. Restart untuk menerapkan.`}},onlyChanged:{t:0,b:{t:2,i:[{t:3}],s:`Hanya pengaturan yang Anda ubah di sini yang ditulis ke KlipperScreen.conf.`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Simpan pengaturan`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Tersimpan - restart KlipperScreen untuk menerapkan.`}},unset:{t:0,b:{t:2,i:[{t:3}],s:`Biarkan tidak diatur (default)`}},never:{t:0,b:{t:2,i:[{t:3}],s:`Tidak pernah (selalu menyala)`}},fontSize:{small:{t:0,b:{t:2,i:[{t:3}],s:`Kecil`}},medium:{t:0,b:{t:2,i:[{t:3}],s:`Sedang`}},large:{t:0,b:{t:2,i:[{t:3}],s:`Besar`}},max:{t:0,b:{t:2,i:[{t:3}],s:`Maks`}}},label:{theme:{t:0,b:{t:2,i:[{t:3}],s:`Tema`}},language:{t:0,b:{t:2,i:[{t:3}],s:`Bahasa`}},screen_blanking:{t:0,b:{t:2,i:[{t:3}],s:`Sleep layar setelah`}},font_size:{t:0,b:{t:2,i:[{t:3}],s:`Ukuran font`}},"24htime":{t:0,b:{t:2,i:[{t:3}],s:`Format 24 jam`}},use_dpms:{t:0,b:{t:2,i:[{t:3}],s:`Gunakan DPMS untuk mematikan layar`}},show_cursor:{t:0,b:{t:2,i:[{t:3}],s:`Tampilkan kursor mouse`}},confirm_estop:{t:0,b:{t:2,i:[{t:3}],s:`Konfirmasi sebelum emergency stop`}},show_heater_power:{t:0,b:{t:2,i:[{t:3}],s:`Tampilkan % daya pemanas`}},autoclose_popups:{t:0,b:{t:2,i:[{t:3}],s:`Tutup pop-up otomatis`}}}},kiosk:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Memeriksa layar…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Tampilkan FilaMind Flow sendiri di layar sentuh sebagai peramban layar penuh - kendali total atas apa yang ditampilkan layar. Ia bertukar dengan KlipperScreen: menjalankan satu menghentikan yang lain.`}},current:{t:0,b:{t:2,i:[{t:3}],s:`Layar sekarang`}},mode:{kiosk:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk FilaMind`}},klipperscreen:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen`}},none:{t:0,b:{t:2,i:[{t:3}],s:`Tidak ada yang berjalan`}}},notInstalled:{t:0,b:{t:2,i:[{t:3}],s:`Kiosk belum dipasang`}},setupHint:{t:0,b:{t:2,i:[{t:3}],s:`Jalankan ini sekali pada host printer (memasang peramban layar penuh + layanan kiosk):`}},persist:{t:0,b:{t:2,i:[{t:3}],s:`Jadikan default saat boot (jika tidak, pertukaran bersifat sementara - reboot memulihkan yang lain).`}},safety:{t:0,b:{t:2,i:[{t:3}],s:`Sementara secara default: reboot mengembalikan yang lain. Jika layar pernah menjadi gelap, lewat SSH jalankan: sudo systemctl start KlipperScreen`}},switchBtn:{t:0,b:{t:2,i:[{t:3}],s:`Beralih ke FilaMind`}},restoreBtn:{t:0,b:{t:2,i:[{t:3}],s:`Pulihkan KlipperScreen`}},refresh:{t:0,b:{t:2,i:[{t:3}],s:`Segarkan`}},confirmSwitchTitle:{t:0,b:{t:2,i:[{t:3}],s:`Tampilkan FilaMind di layar?`}},confirmRestoreTitle:{t:0,b:{t:2,i:[{t:3}],s:`Pulihkan KlipperScreen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Ini menghentikan satu layanan layar dan menjalankan yang lain. Tidak memengaruhi cetakan yang aktif, tetapi layar sentuh akan menjadi hitam selama beberapa detik saat beralih.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Lakukan`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Batal`}},switchedNote:{t:0,b:{t:2,i:[{t:3}],s:`FilaMind sedang mengambil alih layar - seharusnya muncul dalam beberapa detik.`}},restoredNote:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen sedang kembali - layar seharusnya pulih sebentar lagi.`}}},menus:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Memuat menu…`}},intro:{t:0,b:{t:2,i:[{t:3}],s:`Rancang apa yang ditampilkan layar sentuh: tombol setiap menu, urutannya, dan fungsi masing-masing. Grid layar beranda adalah pohon __main; layar cetak adalah __print.`}},addItem:{t:0,b:{t:2,i:[{t:3}],s:`Tambah tombol`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Belum ada item - tambahkan satu.`}},up:{t:0,b:{t:2,i:[{t:3}],s:`Naik`}},down:{t:0,b:{t:2,i:[{t:3}],s:`Turun`}},addChild:{t:0,b:{t:2,i:[{t:3}],s:`Tambah sub-item`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Hapus`}},name:{t:0,b:{t:2,i:[{t:3}],s:`Nama`}},icon:{t:0,b:{t:2,i:[{t:3}],s:`Ikon`}},action:{t:0,b:{t:2,i:[{t:3}],s:`Aksi`}},actSubmenu:{t:0,b:{t:2,i:[{t:3}],s:`Buka sub-menu`}},actPanel:{t:0,b:{t:2,i:[{t:3}],s:`Buka layar`}},actGcode:{t:0,b:{t:2,i:[{t:3}],s:`Jalankan G-code`}},panel:{t:0,b:{t:2,i:[{t:3}],s:`Layar`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},enable:{t:0,b:{t:2,i:[{t:3}],s:`Tampilkan jika`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Simpan menu`}},newItem:{t:0,b:{t:2,i:[{t:3}],s:`Tombol baru`}},savedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Menu tersimpan - restart KlipperScreen untuk melihatnya.`}}},themes:{loading:{t:0,b:{t:2,i:[{t:3}],s:`Memuat tema…`}},palette:{t:0,b:{t:2,i:[{t:3}],s:`Palet`}},radius:{t:0,b:{t:2,i:[{t:3}],s:`Radius sudut`}},preview:{t:0,b:{t:2,i:[{t:3}],s:`Pratinjau langsung`}},btn:{t:0,b:{t:2,i:[{t:3}],s:`Tombol`}},previewWarn:{t:0,b:{t:2,i:[{t:3}],s:`peringatan`}},previewApprox:{t:0,b:{t:2,i:[{t:3}],s:`Pratinjau perkiraan - layar sebenarnya dirender dengan GTK; perbedaan kecil dapat terjadi.`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Nama tema baru`}},createApply:{t:0,b:{t:2,i:[{t:3}],s:`Buat & terapkan`}},createOnly:{t:0,b:{t:2,i:[{t:3}],s:`Buat saja`}},installed:{t:0,b:{t:2,i:[{t:3}],s:`Tema terpasang`}},apply:{t:0,b:{t:2,i:[{t:3}],s:`Terapkan`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Hapus tema`}},generated:{t:0,b:{t:2,i:[{t:3}],s:`Dibuat di sini`}},created:{t:0,b:{t:2,i:[{t:3}],s:`Tema dibuat. Terapkan dari daftar, lalu restart.`}},appliedRestart:{t:0,b:{t:2,i:[{t:3}],s:`Tema diatur - restart KlipperScreen untuk melihatnya.`}},previewTitle:{t:0,b:{t:2,i:[{t:3}],s:`Printer`}}},restart:{button:{t:0,b:{t:2,i:[{t:3}],s:`Mulai ulang KlipperScreen`}},restarting:{t:0,b:{t:2,i:[{t:3}],s:`Me-restart…`}},done:{t:0,b:{t:2,i:[{t:3}],s:`KlipperScreen sedang restart - layar akan dimuat ulang sebentar lagi.`}},confirmTitle:{t:0,b:{t:2,i:[{t:3}],s:`Mulai ulang KlipperScreen?`}},confirmBody:{t:0,b:{t:2,i:[{t:3}],s:`Ini me-restart layanan layar sentuh untuk menerapkan perubahan Anda. Tidak memengaruhi cetakan yang aktif, tetapi layar menjadi kosong selama beberapa detik.`}},confirm:{t:0,b:{t:2,i:[{t:3}],s:`Mulai ulang`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Batal`}}}}};export{e as default};